const state=JSON.parse(JSON.stringify($context.$variables.supplierState)),p=state.childDispatch||{},a=state.attempts.filter(function(a){return a.kind===p.kind&&a.requestId===p.requestId&&a.revision===p.revision;})[0],address=p.kind==='address',key=address?'SupplierAddressId':'SupplierContactId',r=$context.$nodes[address?'XDX_GET_CREATED_ADDRESS':'XDX_GET_CREATED_CONTACT'].$output;
 if(!a||a.status!=='accepted')throw new Error('No matching accepted child attempt exists.');
 function decimal(v){return typeof v==='number'&&Number.isSafeInteger(v)&&v>0?String(v):typeof v==='string'&&/^[1-9][0-9]{0,17}$/.test(v)?v:null;}
 const fields=address?['AddressName','CountryCode','AddressLine1','City','State','PostalCode','Email','AddressPurposeOrderingFlag']:['FirstName','LastName','Email'];
 const generatedMatch=r&&(address?(a.AddressPartyNumber===undefined||String(r.AddressPartyNumber)===String(a.AddressPartyNumber)):(a.PersonProfileId===undefined||decimal(r.PersonProfileId)===decimal(a.PersonProfileId)));
 const matches=generatedMatch&&r&&decimal(r[key])===a[key]&&String(a.suppliers_Id)===String(p.suppliers_Id)&&fields.every(function(f){return r[f]===a.payload[f];})&&(address||Object.prototype.hasOwnProperty.call(r,'PersonProfileId')&&!!decimal(r.PersonProfileId)&&Object.prototype.hasOwnProperty.call(r,'UserName')&&r.UserName===null&&Object.prototype.hasOwnProperty.call(r,'UserAccountStatus')&&r.UserAccountStatus===null);
 a.verification=matches?'verified':'mismatch-or-unavailable';state.nextOperation='display';state.response={message:matches?(address?'Address':'Contact')+' created and independently verified.':'The '+p.kind+' was created, but its saved required fields or relationships could not be verified. It will not be created again.',kind:p.kind,requestId:a.requestId,revision:a.revision,supplier:state.draft&&state.draft.supplier,attempt:JSON.parse(JSON.stringify(a)),verification:a.verification};
 if(matches){state.response.item=JSON.parse(JSON.stringify(r));const resource=address?'addresses':'contacts';state.childSelections=state.childSelections||{};state.childSelections[resource]={suppliers_Id:p.suppliers_Id,item:JSON.parse(JSON.stringify(r))};state.draft=null;delete state.childDispatch;}state.response.acceptedText=acceptedChildText(state.response,false);return {state:state,operation:'display'};
function acceptedChildText(response,recorded){
 const attempts=response.attempt?[response.attempt]:response.attempts;
 if(!Array.isArray(attempts)||attempts.length!==1)return null;
 const a=attempts[0];if(!a||a.status!=='accepted'||['address','contact'].indexOf(a.kind)<0)return null;
 const address=a.kind==='address',key=address?'SupplierAddressId':'SupplierContactId';
 const lines=[response.message||'Recorded child creation outcome.'];
 if(recorded)lines.push('Previously recorded creation outcome. No new creation or verification was performed for this display.');
 lines.push('Kind: '+a.kind,'Mode: '+a.mode,'Status: '+a.status,'Verification: '+a.verification,'Request: '+a.requestId+' revision '+a.revision);
 if(a.suppliers_Id!==undefined&&a.suppliers_Id!==null)lines.push('Parent supplier ID: '+a.suppliers_Id);
 const parent=response.supplier&&String(response.supplier.SupplierId)===String(a.suppliers_Id)?response.supplier:null;
 if(parent&&typeof parent.Supplier==='string')lines.push('Parent supplier: '+parent.Supplier);
 if(parent&&parent.SupplierNumber!==undefined&&parent.SupplierNumber!==null)lines.push('Supplier number: '+parent.SupplierNumber);
 if(a.mode==='template'&&a.sourceId!==undefined&&a.sourceId!==null)lines.push('Source '+a.kind+' ID: '+a.sourceId);
 if(a[key]!==undefined&&a[key]!==null)lines.push('Created '+a.kind+' ID: '+a[key]);
 const own=response.item&&String(response.item[key])===String(a[key])?response.item:null,generated=address?'AddressPartyNumber':'PersonProfileId';
 const generatedValue=Object.prototype.hasOwnProperty.call(a,generated)?a[generated]:own&&Object.prototype.hasOwnProperty.call(own,generated)?own[generated]:undefined;
 if(generatedValue!==undefined&&generatedValue!==null)lines.push(generated+': '+generatedValue);
 lines.push(a.verification==='verified'?'Saved required fields verified against the approved payload:':'Submitted required fields (saved values not verified):');
 const fields=address?['AddressName','CountryCode','AddressLine1','City','State','PostalCode','Email','AddressPurposeOrderingFlag']:['FirstName','LastName','Email'];
 fields.forEach(function(field){if(a.payload&&Object.prototype.hasOwnProperty.call(a.payload,field))lines.push(field+': '+a.payload[field]);});
 return lines.join('\n');
}
